const VIP_USD = $env.VIP_MONTHLY_USD || '45';
const WORKSHOP_MEM = $env.WORKSHOP_MEMBER_PRICE || '4,000';
const WORKSHOP_NON = $env.WORKSHOP_NONMEMBER_PRICE || '6,000';
const PRIVATE_USD = $env.PRIVATE_SESSION_USD || '100';
const GROQ_KEY = $env.GROQ_API_KEY || '';
const OPENAI_KEY = $env.OPENAI_API_KEY || '';
const GEMINI_KEY = $env.GEMINI_API_KEY || '';
