async function runTool(db, act, ctx) {
  const tool = String(act?.tool || 'direct_answer');
  const args = act?.args || {};

  if (tool === 'get_market_prices') {
    return { tool, ok: true, livePrices: ctx.livePrices };
  }

  if (tool === 'get_system_kpis') {
    return { tool, ok: true, ...ctx.stats, livePrices: ctx.livePrices };
  }

  if (tool === 'trigger_workflow') {
    const wfPath = String(args.workflow_path || '').replace(/^\/+/, '');
    if (!wfPath) return { tool, ok: false, error: 'Missing workflow_path' };
    try {
      const hdrs = { 'Content-Type': 'application/json' };
      if (BRIDGE_SECRET) hdrs['x-tradesejon-secret'] = BRIDGE_SECRET;
      const r = await fetch(`${N8N_INTERNAL}/webhook/${wfPath}`, {
        method: 'POST',
        headers: hdrs,
        body: JSON.stringify(args.payload || {}),
        signal: AbortSignal.timeout(6000)
      });
      return { tool, ok: r.ok, workflow: wfPath, status: r.status };
    } catch (e) {
      return { tool, ok: false, workflow: wfPath, error: e.message };
    }
  }

  if (tool === 'search_system') {
    const q = String(args.query || ctx.prompt || '').trim();
    const scope = String(args.scope || 'all').toLowerCase();
    const out = { tool, ok: true, crm: [], tickets: [], knowledge: [] };
    if (!db) return { ...out, ok: false, error: 'MongoDB not configured in n8n .env' };
    const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    if (scope === 'all' || scope === 'crm') {
      const leads = await db.collection('trading_leads').find({ $or: [{ full_name: rx }, { email: rx }, { phone: rx }] }).limit(5).toArray().catch(() => []);
      const contacts = await db.collection('contacts').find({ $or: [{ full_name: rx }, { name: rx }, { email: rx }, { phone: rx }] }).limit(5).toArray().catch(() => []);
      out.crm = [...leads, ...contacts].map(d => ({ name: d.full_name || d.name || 'Lead', email: d.email || '', phone: d.phone || '', status: d.status || '' }));
    }
    if (scope === 'all' || scope === 'knowledge') {
      const kb = await db.collection('kb_articles').find({ $or: [{ title: rx }, { content: rx }] }).limit(5).toArray().catch(() => []);
      out.knowledge = kb.map(k => ({ title: k.title, snippet: String(k.content || '').slice(0, 180) }));
    }
    return out;
  }

  if (tool === 'list_knowledge') {
    if (!db) return { tool, ok: true, count: 0, items: [] };
    const items = await db.collection('kb_articles').find({}).sort({ updated_at: -1 }).limit(20).toArray().catch(() => []);
    return { tool, ok: true, count: items.length, items: items.map(i => ({ title: i.title, slug: i.slug })) };
  }

  if (tool === 'add_knowledge') {
    const title = String(args.title || 'Synced Rule').trim();
    const content = String(args.content || '').trim();
    if (!content) return { tool, ok: false, error: 'Missing knowledge content' };
    const slug = (title.toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 48) || 'rule') + '_' + Date.now().toString(36).slice(-4);
    if (db) {
      await db.collection('kb_articles').updateOne({ slug }, { $set: { slug, title, category: String(args.category || 'general'), content, updated_at: new Date() } }, { upsert: true }).catch(() => {});
      await db.collection('knowledge_chunks').insertOne({ slug, title, chunk_index: 0, text: content.slice(0, 2000), updated_at: new Date() }).catch(() => {});
      await db.collection('aios_super_memory').insertOne({ type: 'n8n_knowledge_ingest', slug, title, rule: content, updated_at: new Date() }).catch(() => {});
    }
    return { tool, ok: true, title, slug, chunks: 1 };
  }

  if (tool === 'delete_knowledge') {
    const q = String(args.slug_or_query || '').trim();
    if (!q || q === '*' || q.toLowerCase() === 'all') return { tool, ok: false, error: 'Wildcard deletion blocked by safety guard.' };
    if (!db) return { tool, ok: false, error: 'MongoDB not connected' };
    const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    const doc = await db.collection('kb_articles').findOne({ $or: [{ slug: q }, { title: rx }] }).catch(() => null);
    if (!doc) return { tool, ok: false, error: `No knowledge entry matched "${q}".` };
    await db.collection('kb_articles').deleteOne({ slug: doc.slug }).catch(() => {});
    await db.collection('knowledge_chunks').deleteMany({ slug: doc.slug }).catch(() => {});
    return { tool, ok: true, deleted_title: doc.title, deleted_slug: doc.slug };
  }

  if (tool === 'add_crm_lead') {
    const name = String(args.name || 'New Lead').trim();
    const email = String(args.email || '').trim().toLowerCase();
    const phone = String(args.phone || '').trim();
    if (!email && !phone) return { tool, ok: false, error: 'Provide an email or phone number to save lead.' };
    if (db) {
      const f = email ? { email } : { phone };
      const doc = { name, full_name: name, email: email || undefined, phone: phone || undefined, status: String(args.status || 'prospect'), updatedAt: new Date() };
      await db.collection('trading_leads').updateOne(f, { $set: doc, $setOnInsert: { createdAt: new Date() } }, { upsert: true }).catch(() => {});
      await db.collection('contacts').updateOne(f, { $set: doc, $setOnInsert: { createdAt: new Date() } }, { upsert: true }).catch(() => {});
    }
    return { tool, ok: true, name, email, phone };
  }

  if (tool === 'delete_crm_contact') {
    const target = String(args.target || '').trim();
    if (!target || target === '*' || target.toLowerCase() === 'all') return { tool, ok: false, error: 'Wildcard deletion blocked by safety guard.' };
    if (!db) return { tool, ok: false, error: 'MongoDB not connected' };
    const rx = new RegExp(`^${target.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, 'i');
    const f = { $or: [{ email: target.toLowerCase() }, { phone: target }, { full_name: rx }, { name: rx }] };
    const [r1, r2, r3] = await Promise.all([
      db.collection('trading_leads').deleteOne(f).catch(() => ({ deletedCount: 0 })),
      db.collection('contacts').deleteOne(f).catch(() => ({ deletedCount: 0 })),
      db.collection('leads').deleteOne(f).catch(() => ({ deletedCount: 0 }))
    ]);
    const deleted = (r1.deletedCount || 0) + (r2.deletedCount || 0) + (r3.deletedCount || 0);
    if (!deleted) return { tool, ok: false, error: `No CRM record matched "${target}".` };
    await db.collection('audit_logs').insertOne({ action: 'n8n_delete_crm', target, deleted, at: new Date() }).catch(() => {});
    return { tool, ok: true, target, deleted_records: deleted };
  }

  if (tool === 'approve_lead') {
    const target = String(args.target || 'latest').trim();
    if (!db) return { tool, ok: false, error: 'MongoDB not connected' };
    let lead = null;
    if (/^(?:latest|last|newest|recent|آخر|اخر|أحدث|احدث)$/i.test(target)) {
      const arr = await db.collection('trading_leads').find({}).sort({ createdAt: -1, _id: -1 }).limit(1).toArray().catch(() => []);
      lead = arr[0] || (await db.collection('leads').find({}).sort({ createdAt: -1, _id: -1 }).limit(1).toArray().catch(() => []))[0] || null;
    } else {
      lead = await resolveProfile(db, target);
    }
    if (!lead) return { tool, ok: false, error: `No lead matched "${target}".` };
    const name = lead.full_name || lead.name || 'Trader';
    const email = String(lead.email || '').trim().toLowerCase();
    const updF = lead._id ? { _id: lead._id } : (email ? { email } : { full_name: name });
    await Promise.all([
      db.collection('trading_leads').updateOne(updF, { $set: { status: 'approved', approvedAt: new Date() } }).catch(() => {}),
      db.collection('leads').updateOne(email ? { email } : updF, { $set: { status: 'approved', approvedAt: new Date() } }).catch(() => {}),
      db.collection('contacts').updateOne(email ? { email } : updF, { $set: { status: 'approved', approvedAt: new Date() } }).catch(() => {})
    ]);
    let emailSent = false, messageId = '', errMsg = '';
    if (email) {
      const mr = await sendSmtpEmail(email, `${BRAND} VIP Access Approved`, `<p>Welcome ${escHtml(name)}, your ${escHtml(BRAND)} VIP application has been approved.</p>`);
      emailSent = Boolean(mr.ok);
      messageId = mr.messageId || '';
      errMsg = mr.error || '';
    }
    return { tool, ok: true, name, email, emailSent, messageId, error: errMsg || undefined };
  }

  if (tool === 'update_campaign_settings') {
    const setObj = { updatedAt: new Date() };
    if (args.session_time) setObj.startAt = String(args.session_time).trim();
    if (args.zoom_url) setObj.zoomMeetingUrl = String(args.zoom_url).trim();
    if (args.whop_url) setObj.whopCheckoutUrl = String(args.whop_url).trim();
    if (db) {
      await db.collection('campaigns').updateOne({ _id: 'workshop-poc' }, { $set: setObj }, { upsert: true }).catch(() => {});
      await db.collection('aios_config').updateOne({ key: 'session_settings' }, { $set: { session_time: setObj.startAt || '', zoom_url: setObj.zoomMeetingUrl || '', updated_at: new Date().toISOString() } }, { upsert: true }).catch(() => {});
    }
    return { tool, ok: true, updated: setObj };
  }

  if (tool === 'send_email') {
    const prof = await resolveProfile(db, args.target || '').catch(() => null);
    const toEmail = prof?.email || (String(args.target || '').includes('@') ? String(args.target).trim().toLowerCase() : '');
    if (!toEmail) return { tool, ok: false, error: `Email not found for "${args.target || ''}".` };
    const mr = await sendSmtpEmail(toEmail, `${BRAND} Executive Update`, `<p>${escHtml(args.content || ctx.prompt)}</p>`);
    if (mr.ok && db) await db.collection('outbound_emails').insertOne({ to: toEmail, subject: `${BRAND} Executive Update`, messageId: mr.messageId, sentAt: new Date(), status: 'sent' }).catch(() => {});
    return { tool, ok: Boolean(mr.ok), to: toEmail, messageId: mr.messageId, error: mr.error };
  }

  if (tool === 'send_discord_dm') {
    if (!DISCORD_TOK) return { tool, ok: false, error: 'DISCORD_BOT_TOKEN not configured in n8n .env' };
    const prof = await resolveProfile(db, args.target || '').catch(() => null);
    const did = /^\d{16,21}$/.test(String(args.target || '').trim()) ? String(args.target).trim() : (prof?.discord_user_id || '');
    if (!did) return { tool, ok: false, error: `Discord User ID not found for "${args.target || ''}".` };
    const ch = await fetch('https://discord.com/api/v10/users/@me/channels', {
      method: 'POST', headers: { 'Authorization': `Bot ${DISCORD_TOK}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ recipient_id: did })
    }).then(r => r.json()).catch(() => ({}));
    if (!ch.id) return { tool, ok: false, error: ch.message || 'Discord DM channel rejected' };
    const sent = await fetch(`https://discord.com/api/v10/channels/${ch.id}/messages`, {
      method: 'POST', headers: { 'Authorization': `Bot ${DISCORD_TOK}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ content: String(args.message || 'Executive update') })
    }).then(r => r.json()).catch(() => ({}));
    return { tool, ok: Boolean(sent.id), userId: did, messageId: sent.id, error: sent.message };
  }

  if (tool === 'send_telegram_dm') {
    const rawT = String(args.target || '').trim();
    const msg = String(args.message || 'Executive notification').trim();
    const linkM = rawT.match(/https?:\/\/t\.me\/contact\/([0-9]{5,16})/i);
    let cid = linkM ? linkM[1] : (/^\d{5,16}$/.test(rawT) ? rawT : '');
    if (!cid && rawT && db) {
      const prof = await resolveProfile(db, rawT.replace(/^@/, ''));
      cid = prof?.chatId || prof?.telegram?.chatId || '';
    }
    if (!cid) return { tool, ok: false, broadcast_prevented: true, error: `Could not resolve numeric Telegram chat_id for "${rawT}". No broadcast triggered.` };
    const tok = TG_TRADER_TOK || TG_CEO_TOK;
    const res = await tgApi(tok, 'sendMessage', { chat_id: cid, text: escHtml(msg), parse_mode: 'HTML' });
    return { tool, ok: Boolean(res.ok), single_user_only: true, chatId: cid, messageId: res.result?.message_id, error: res.description };
  }

  if (tool === 'broadcast_telegram') {
    const msg = String(args.message || '').trim();
    if (!msg) return { tool, ok: false, error: 'Missing broadcast message' };
    const tok = TG_TRADER_TOK || TG_CEO_TOK;
    if (!tok) return { tool, ok: false, error: 'TELEGRAM_TRADER_BOT_TOKEN not configured in n8n .env' };
    const cids = await collectSubscriberChatIds(db);
    let sent = 0, failed = 0;
    for (const cid of cids) {
      const r = await tgApi(tok, 'sendMessage', { chat_id: cid, text: escHtml(msg), parse_mode: 'HTML' });
      if (r && r.ok) sent++; else failed++;
    }
    return { tool, ok: sent > 0, sent, failed, total: cids.length };
  }

  return { tool: 'direct_answer', ok: true };
}

async function runAgenticBrain(userPrompt, { channel = 'aios_n8n', history = [], wantVoice = false, tgReplyChatId = '', tgReplyTok = '' } = {}) {
  const prompt = String(userPrompt || '').trim();
  const livePrices = await fetchLiveMarketPrices();

  const faqAns = matchFaq(prompt);
  if (faqAns) {
    if (tgReplyChatId && tgReplyTok) await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: faqAns, parse_mode: 'HTML' });
    return { ok: true, engine: 'n8n_agentic_brain', thought: 'Matched official Knowledge Base', actions: [{ tool: 'faq_knowledge_query', ok: true }], reply: faqAns, voice_enabled: false, audioBase64: null };
  }

  const tgLinkM = prompt.match(/https?:\/\/t\.me\/contact\/([0-9]{5,16})(?::[^\s]+)?/i);
  if (tgLinkM && !/(?:everyone|all subscribers|للكل|لكل المتداولين)/i.test(prompt)) {
    const targetCid = tgLinkM[1];
    const afterLink = prompt.slice(tgLinkM.index + tgLinkM[0].length)
      .replace(/^(?:2ollo|2olo|2olha|قوله|قولها|بلغه|en|inn|that|saying|msg|message|:|-|\s)+/i, '').trim() || 'Executive notification';
    const r = await runTool(null, { tool: 'send_telegram_dm', args: { target: targetCid, message: afterLink } }, { prompt, livePrices });
    const rep = r.ok
      ? `✅ <b>Verified Delivered to Single Telegram User Only (No Broadcast)!</b>\n🆔 Chat ID: <code>${escHtml(targetCid)}</code>\n📝 Message: "${escHtml(afterLink)}"`
      : `⚠️ Telegram delivery rejected for Chat ID <code>${escHtml(targetCid)}</code>: ${escHtml(r.error || 'Forbidden')}. No broadcast was sent.`;
    if (tgReplyChatId && tgReplyTok) await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: rep, parse_mode: 'HTML' });
    return { ok: r.ok, engine: 'n8n_agentic_brain', thought: 'Targeted single-user Telegram DM firewall', actions: [r], reply: rep, voice_enabled: false, audioBase64: null };
  }

  return await withMongo(async (db) => {
    const [campDoc, nContacts, nLeads, nTrading, nEmails, kbItems] = db ? await Promise.all([
      db.collection('campaigns').findOne({ _id: 'workshop-poc' }).catch(() => null),
      db.collection('contacts').countDocuments().catch(() => 0),
      db.collection('leads').countDocuments().catch(() => 0),
      db.collection('trading_leads').countDocuments().catch(() => 0),
      db.collection('outbound_emails').countDocuments().catch(() => 0),
      db.collection('kb_articles').find({}).sort({ updated_at: -1 }).limit(5).toArray().catch(() => [])
    ]) : [null, 0, 0, 0, 0, []];

    const stats = { nContacts, nLeadsV2: nLeads, nTradingLeads: nTrading, nOutboundEmails: nEmails };
    const kbTxt = (kbItems || []).length ? '\nKB Entries: ' + kbItems.map(k => k.title).join(', ') : '';
    const ctxSum = `Channel: ${channel}\nLive Prices: ${livePrices}\nSession: ${campDoc?.startAt || SCHEDULE}\nCRM Stats: contacts=${nContacts}, leads=${nLeads}, trading_leads=${nTrading}, emails=${nEmails}${kbTxt}`;

    let plan = await planWithLlm(prompt, ctxSum, history);
    if (!plan) {
      const low = prompt.toLowerCase();
      if (/^(?:approve|accept|اعتمد|اقبل|موافقة)(?=\s|$|[:.,!؟?])/i.test(low)) {
        plan = { thought: 'Fallback approve lead', actions: [{ tool: 'approve_lead', args: { target: 'latest' } }], reply_html: '' };
      } else if (/^(?:list\s+(?:all\s+)?(?:kb|knowledge)|قائمة\s+المعرفة|اعرض\s+المعرفة)/i.test(low)) {
        plan = { thought: 'Fallback list KB', actions: [{ tool: 'list_knowledge', args: {} }], reply_html: '' };
      } else if (/(?:\b(?:kpis?|stats|metrics)\b|احصائيات|إحصائيات|حالة\s+السيستم)/i.test(low)) {
        plan = { thought: 'Fallback KPIs', actions: [{ tool: 'get_system_kpis', args: {} }], reply_html: '' };
      } else if (/(?:جلسة|جلسه|سيشن|session)\s*(?:النهاردة|اليوم|today)?\s*(?:الساعة|الساعه|at)?\s*([0-9]{1,2}(?::[0-9]{2})?)/i.test(prompt)) {
        const tm = prompt.match(/(?:جلسة|جلسه|سيشن|session)\s*(?:النهاردة|اليوم|today)?\s*(?:الساعة|الساعه|at)?\s*([0-9]{1,2}(?::[0-9]{2})?)/i)[1];
        const acts = [{ tool: 'update_campaign_settings', args: { session_time: `${tm} PM (بتوقيت القاهرة)` } }];
        if (/(?:بلغ|نبه|اعلن|notify|announce|subscribers|مشتركين|الكل)/i.test(prompt)) {
          acts.push({ tool: 'broadcast_telegram', args: { message: `📢 تحديث موعد الجلسة المباشرة: النهاردة الساعة ${tm} PM بتوقيت القاهرة!` } });
        }
        plan = { thought: 'Fallback campaign session update', actions: acts, reply_html: '' };
      } else if (/(?:price|prices|gold|btc|الدهب|الذهب|البيتكوين|سعر)/i.test(low)) {
        plan = { thought: 'Fallback market prices', actions: [{ tool: 'get_market_prices', args: {} }], reply_html: '' };
      } else {
        plan = { thought: 'Fallback status summary', actions: [{ tool: 'direct_answer', args: {} }], reply_html: `🤖 <b>${escHtml(BRAND)} n8n Autonomous Agent</b>\n• Live Prices: ${escHtml(livePrices)}\n• CRM: Contacts=${nContacts}, Leads=${nTrading}, Emails=${nEmails}` };
      }
    }

    const actions = [];
    const lines = [];
    for (const a of (plan.actions || [])) {
      if (!a || !a.tool || a.tool === 'direct_answer') { actions.push({ tool: 'direct_answer', ok: true }); continue; }
      const r = await runTool(db, a, { prompt, livePrices, stats });
      actions.push(r);
      if (!r.ok) lines.push(`⚠️ <b>${escHtml(r.tool)}:</b> ${escHtml(r.error || 'Failed')}`);
      else if (r.tool === 'get_system_kpis') lines.push(`📊 <b>Live KPIs:</b> Contacts=${r.nContacts}, Leads=${r.nLeadsV2}, TradingLeads=${r.nTradingLeads}, Emails=${r.nOutboundEmails}`);
      else if (r.tool === 'get_market_prices') lines.push(`📈 <b>Live Market Prices:</b> ${escHtml(r.livePrices)}`);
      else if (r.tool === 'list_knowledge') lines.push(`📚 <b>Knowledge Base (${r.count}):</b> ` + (r.items || []).map(i => escHtml(i.title)).join(', '));
      else if (r.tool === 'add_knowledge') lines.push(`✅ <b>Synced Knowledge:</b> ${escHtml(r.title)}`);
      else if (r.tool === 'delete_knowledge') lines.push(`🗑️ <b>Deleted Knowledge:</b> ${escHtml(r.deleted_title)}`);
      else if (r.tool === 'search_system') lines.push(`🔍 <b>Search Results:</b> CRM=${r.crm.length}, KB=${r.knowledge.length}`);
      else if (r.tool === 'add_crm_lead') lines.push(`✅ <b>Saved Lead:</b> ${escHtml(r.name)}`);
      else if (r.tool === 'delete_crm_contact') lines.push(`🗑️ <b>Deleted CRM Record:</b> ${escHtml(r.target)} (${r.deleted_records})`);
      else if (r.tool === 'approve_lead') lines.push(`✅ <b>Approved Lead:</b> ${escHtml(r.name)}` + (r.emailSent ? ` | Email Sent (${escHtml(r.email)})` : ''));
      else if (r.tool === 'update_campaign_settings') lines.push(`🎯 <b>Campaign Updated:</b> ${escHtml(r.updated?.startAt || 'Saved')}`);
      else if (r.tool === 'broadcast_telegram') lines.push(`📣 <b>Broadcast Sent:</b> ${r.sent}/${r.total} subscribers`);
      else if (r.tool === 'send_telegram_dm') lines.push(`📲 <b>Telegram DM Sent:</b> Chat ID <code>${escHtml(r.chatId)}</code>`);
      else if (r.tool === 'send_discord_dm') lines.push(`💬 <b>Discord DM Sent:</b> User <code>${escHtml(r.userId)}</code>`);
      else if (r.tool === 'send_email') lines.push(`✉️ <b>Email Sent:</b> ${escHtml(r.to)}`);
    }

    const reply = lines.length
      ? lines.join('\n\n') + (plan.reply_html && !actions.some(x => !x.ok) ? `\n\n${plan.reply_html}` : '')
      : (plan.reply_html || '✅ Executed.');

    if (db) {
      await db.collection('aios_super_memory').insertOne({
        channel, prompt, thought: plan.thought, actions, reply, at: new Date()
      }).catch(() => {});
    }

    if (tgReplyChatId && tgReplyTok) {
      await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: reply, parse_mode: 'HTML' });
    }

    let audioBase64 = null;
    if (wantVoice && ELEVEN_KEY) {
      try {
        const plain = reply.replace(/<[^>]+>/g, '').slice(0, 400);
        const ttsRes = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${ELEVEN_VOICE}`, {
          method: 'POST',
          headers: { 'xi-api-key': ELEVEN_KEY, 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: plain, model_id: 'eleven_multilingual_v2' }),
          signal: AbortSignal.timeout(6000)
        });
        if (ttsRes.ok) audioBase64 = Buffer.from(await ttsRes.arrayBuffer()).toString('base64');
      } catch (_) {}
    }

    return {
      ok: true,
      engine: 'n8n_agentic_brain',
      thought: plan.thought || 'n8n execution completed',
      actions,
      actionsExecuted: actions,
      reply,
      voice_enabled: Boolean(audioBase64),
      audioBase64
    };
  });
}


